def transform(grid):
    h, w = len(grid), len(grid[0])

    divider_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    divider_cols = {
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
    }

    row_segments = []
    start = 0
    for r in range(h + 1):
        if r == h or r in divider_rows:
            if start < r:
                row_segments.append((start, r))
            start = r + 1

    col_segments = []
    start = 0
    for c in range(w + 1):
        if c == w or c in divider_cols:
            if start < c:
                col_segments.append((start, c))
            start = c + 1

    counts = {}
    for r0, r1 in row_segments:
        for c0, c1 in col_segments:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    color = grid[r][c]
                    counts[color] = counts.get(color, 0) + 1

    background = max(counts, key=counts.get)
    output = []
    for r0, r1 in row_segments:
        row = []
        for c0, c1 in col_segments:
            cell_counts = {}
            for r in range(r0, r1):
                for c in range(c0, c1):
                    color = grid[r][c]
                    if color != background:
                        cell_counts[color] = cell_counts.get(color, 0) + 1
            row.append(1 if any(n >= 2 for n in cell_counts.values()) else background)
        output.append(row)
    return output
